1: // RFC 8785 (JCS) canonicalization for UIA-CORE-001.
2: //
3: // Provides deterministic JSON canonicalization over the strict JsonValue data
4: // model defined in primitives.ts, plus SHA-256 hashing of the UTF-8 bytes of
5: // the canonical string. Canonicalization, UTF-8 encoding and hashing are kept
6: // as separate steps (see canonicalSha256 for a convenience composition).
7: 
8: import type { JsonValue } from './primitives.js';
9: import { CanonicalizationError } from './errors.js';
10: import { sha256Hex } from './sha256.js';
11: import { validateJsonValue } from './ownership.js';
12: 
13: // ---------------------------------------------------------------------------
14: // Validation (delegated to ownership's strict JSON validator; CanonicalizationError
15: // is thrown instead of returning a Result, since canonicalize() returns string)
16: // ---------------------------------------------------------------------------
17: 
18: function validate(value: unknown): JsonValue {
19:   const result = validateJsonValue(value);
20:   if (!result.ok) {
21:     throw new CanonicalizationError(result.error.message);
22:   }
23:   return result.value;
24: }
25: 
26: // ---------------------------------------------------------------------------
27: // Serialization
28: // ---------------------------------------------------------------------------
29: 
30: function serialize(value: JsonValue): string {
31:   if (value === null) return 'null';
32:   const t = typeof value;
33:   if (t === 'boolean') return value ? 'true' : 'false';
34:   if (t === 'string') return JSON.stringify(value);
35:   if (t === 'number') return JSON.stringify(value);
36:   if (Array.isArray(value)) {
37:     const parts: string[] = [];
38:     for (const item of value) {
39:       parts.push(serialize(item));
40:     }
41:     return '[' + parts.join(',') + ']';
42:   }
43:   if (typeof value === 'object' && value !== null) {
44:     const keys = Object.keys(value).sort((a, b) => {
45:       if (a < b) return -1;
46:       if (a > b) return 1;
47:       return 0;
48:     });
49:     const parts: string[] = [];
50:     for (const k of keys) {
51:       parts.push(JSON.stringify(k) + ':' + serialize((value as Record<string, JsonValue>)[k]));
52:     }
53:     return '{' + parts.join(',') + '}';
54:   }
55:   throw new CanonicalizationError('Unsupported value during serialization');
56: }
57: 
58: // ---------------------------------------------------------------------------
59: // Public API
60: // ---------------------------------------------------------------------------
61: 
62: export function canonicalize(value: JsonValue): string {
63:   // Defensive validation even though the type is JsonValue: callers may cast.
64:   // The serializer operates exclusively on the owned, validated representation.
65:   const validated = validate(value);
66:   return serialize(validated);
67: }
68: 
69: export function canonicalSha256(value: JsonValue): string {
70:   return sha256Hex(new TextEncoder().encode(canonicalize(value)));
71: }

