...
credential.usage: credential.usage,
...
const digest = canonicalSha256(descriptorHashInput(descriptor)); // returns hex
return `urn:hash:sha256:${digest}`;
```
Wait canonicalSha256 returns hex digest (string) — yes, `canonicalSha256` = sha256Hex(encode(canonicalize(value))).

Now tests.

Rewrite D block:
```ts
test('rejects metadata attached to the descriptor instead of hashing a subset', () => {
  const artifacts: Record<string, unknown> = {
    envelope: { envelope_id: 'env-1', sender: 'domain-a' },
    signature: { algorithm: 'ed25519', value: 'sig-bytes' },
    delivery: { received_at: BASE_TIME + 1 },
    ledger: { ingested_at: BASE_TIME + 2 },
    assessment: { assessment_id: 'assessment-1', verified_claims: [] },
    revocation: { credential_id: 'cred-1', reason: 'ROTATION' },
    acceptance: { acceptance_id: 'acceptance-1', decision: 'ACCEPTED' },
    lifecycle: { event_id: 'event-1', new_state: 'SUSPENDED' },
  };

  for (const [key, value] of Object.entries(artifacts)) {
    const raw = { ...descriptor(), [key]: value };
    expect(validateIdentityVersionDescriptor(raw).ok).toBe(false);
    expect(() => descriptorHash(raw as unknown as DeepReadonly<IdentityVersionDescriptor>)).toThrow(CanonicalizationError);
  }
});
```
This is real. Note: each artifact is an unknown root field → rejected. Good.

Optional fields tests:
```ts
describe('optional descriptor fields are part of the hash', () => {
  const optionalCases: ReadonlyArray<readonly [string, IdentityVersionDescriptor]> = [
    ['credential.not_after', descriptor({ public_credentials: [{ ...credential(), not_after: timestamp(BASE_TIME + 10) }] })],
    ['credential.revocation_endpoint_ref', descriptor({ public_credentials: [{ ...credential(), revocation_endpoint_ref: 'https://domain-a/revoke' }] })],
    ['lineage.declared_rationale', descriptor({ lineage: [{ ...lineageLink(), declared_rationale: 'planned rotation' }] })],
    ['lineage.continuity_proof_ref', descriptor({ lineage: [{ ...lineageLink(), continuity_proof_ref: 'proof-1' }] })],
  ];

  for (const [name, candidate] of optionalCases) {
    test(`${name} is projected and affects the hash`, () => {
      const result = validateIdentityVersionDescriptor(candidate);
      expect(result.ok).toBe(true);
      if (!result.ok) return;
      const input = asRecord(descriptorHashInput(result.value));
      // presence check
      ...
      expect(descriptorHash(result.value)).not.toBe(descriptorHash(validated()));
    });
  }
});
```
Presence check needs to navigate nested. Simpler: for each case, compare projection JSON to baseline? Use `JSON.stringify`? Hmm.

Better split:
- Test projection includes optional fields:
```ts
test('projects optional credential fields when present', () => {
  const d = validated({ public_credentials: [{ ...credential(), not_after: timestamp(BASE_TIME + 10), revocation_endpoint_ref: 'https://domain-a/revoke' }] });
  const input = asRecord(descriptorHashInput(d));
  expect(input.public_credentials).toEqual([{ ..., not_after: BASE_TIME + 10, revocation_endpoint_ref: 'https://domain-a/revoke' }]);
});
```
Need full object expected. Fine.
- Similarly lineage.
- Then hash-change tests for each optional with `not.toBe(base)`.

Could combine: for each case, assert hash differs; presence covered by two projection tests.

Known-answer:
```ts
test('matches the pinned hash for a fixed descriptor', () => {
  expect(descriptorHash(validated())).toBe('urn:hash:sha256:<digest>');
});
```
Compute digest.

Also add optional-field presence to projection-shape test? Keep separate.

