import { expect } from 'bun:test';
import type {
  CredentialDescriptor,
  IdentityVersionDescriptor,
  LineageLink,
  LineageRelationType,
  ParticipantKind,
  ParticipantRecord,
  VersionScheme,
} from '../../src/core/entities.js';
import {
  validateCredentialDescriptor,
  validateIdentityVersionDescriptor,
  validateLineageLink,
  validateParticipantRecord,
} from '../../src/core/entities.js';
import type { Registry, StructuralResult } from '../../src/core/lineage.js';
import type { DeepReadonly } from '../../src/core/ownership.js';
import { credentialId, domainId, identityVersionId, participantId, timestamp } from '../../src/core/primitives.js';

export const BASE_TIME = 1_700_000_000_000;

export function participant(id: string, kind: ParticipantKind = 'AGENT'): DeepReadonly<ParticipantRecord> {
  const result = validateParticipantRecord({
    id: participantId(id),
    kind,
    home_domain: domainId('domain-a'),
    registered_at: timestamp(BASE_TIME),
  });
  if (!result.ok) {
    throw new Error(`participant fixture must be valid: ${result.error.message}`);
  }
  return result.value;
}

export function credential(id: string, overrides: Partial<CredentialDescriptor> = {}): DeepReadonly<CredentialDescriptor> {
  const result = validateCredentialDescriptor({
    credential_id: credentialId(id),
    issuer_domain: domainId('domain-a'),
    usage: ['SIGNING'],
    algorithm_family: 'ed25519',
    public_key_canonical: `pk-${id}`,
    not_before: timestamp(BASE_TIME),
    ...overrides,
  });
  if (!result.ok) {
    throw new Error(`credential fixture must be valid: ${result.error.message}`);
  }
  return result.value;
}

export function link(parent: string, relation: LineageRelationType = 'CONTINUATION'): DeepReadonly<LineageLink> {
  const result = validateLineageLink({
    parent_version_id: identityVersionId(parent),
    relation,
  });
  if (!result.ok) {
    throw new Error(`lineage fixture must be valid: ${result.error.message}`);
  }
  return result.value;
}

export function descriptor(input: {
  readonly id: string;
  readonly participant: string;
  readonly lineage?: readonly DeepReadonly<LineageLink>[];
  readonly credentials?: readonly DeepReadonly<CredentialDescriptor>[];
  readonly versionLabel?: string;
  readonly versionScheme?: VersionScheme;
}): DeepReadonly<IdentityVersionDescriptor> {
  const result = validateIdentityVersionDescriptor({
    id: identityVersionId(input.id),
    participant_id: participantId(input.participant),
    version_label: input.versionLabel ?? '1.0.0',
    version_scheme: input.versionScheme ?? 'SEMVER_2',
    declared_protocols: [],
    public_credentials: input.credentials ?? [],
    lineage: input.lineage ?? [],
    published_at: timestamp(BASE_TIME),
  });
  if (!result.ok) {
    throw new Error(`descriptor fixture must be valid: ${result.error.message}`);
  }
  return result.value;
}

export function registry(
  participants: readonly DeepReadonly<ParticipantRecord>[],
  versions: readonly DeepReadonly<IdentityVersionDescriptor>[],
): Registry {
  return {
    participants: () => participants,
    versions: () => versions,
  };
}

/** Stable JSON snapshot used to prove the validator does not mutate Registry contents. */
export function snapshot(registryValue: Registry): string {
  return JSON.stringify([registryValue.participants(), registryValue.versions()]);
}

export function expectRejected(
  result: StructuralResult,
  code: 'ERR_INVALID_RELATION' | 'ERR_INVALID_CARDINALITY',
  parentVersionId?: string,
): void {
  expect(result.status).toBe('REJECTED');
  if (result.status !== 'REJECTED') {
    return;
  }
  expect(result.code).toBe(code);
  if (parentVersionId === undefined) {
    expect('parent_version_id' in result).toBe(false);
  } else {
    expect(result.parent_version_id).toBe(parentVersionId);
  }
}

import { describe, expect, test } from 'bun:test';
import { validateDescriptor } from '../../src/core/lineage.js';
import { credential, descriptor, expectRejected, link, participant, registry, snapshot } from '../support/fixtures.js';

describe('§12 Category A: structural lineage validation', () => {
  test('A-1 valid CONTINUATION is accepted without side effects', () => {
    const alice = participant('participant-a');
    const parentCredential = credential('cred-parent');
    const parent = descriptor({ id: 'iv-a-1', participant: 'participant-a', credentials: [parentCredential] });
    const child = descriptor({
      id: 'iv-a-2',
      participant: 'participant-a',
      lineage: [link('iv-a-1', 'CONTINUATION')],
    });
    const reg = registry([alice], [parent, child]);
    const before = snapshot(reg);

    const result = validateDescriptor(child, reg);

    expect(result).toEqual({ status: 'VALID' });
    expect(snapshot(reg)).toBe(before);
    expect(parent.public_credentials.map((entry) => entry.credential_id)).toEqual(['cred-parent']);
    expect(child.public_credentials).toEqual([]);
    expect(Object.keys(parent)).not.toContain('status');
    expect(JSON.stringify(reg)).not.toContain('DEPRECATED');
    expect(JSON.stringify(reg).toLowerCase()).not.toContain('grant');
  });

  test('A-2 cross-participant CONTINUATION is rejected without state mutation', () => {
    const alice = participant('participant-a');
    const bob = participant('participant-b');
    const parent = descriptor({ id: 'iv-a-1', participant: 'participant-a' });
    const child = descriptor({
      id: 'iv-b-1',
      participant: 'participant-b',
      lineage: [link('iv-a-1', 'CONTINUATION')],
    });
    const reg = registry([alice, bob], [parent, child]);
    const before = snapshot(reg);

    const result = validateDescriptor(child, reg);

    expectRejected(result, 'ERR_INVALID_RELATION', 'iv-a-1');
    expect(snapshot(reg)).toBe(before);
    expect(alice).toBe(reg.participants()[0]);
    expect(parent).toBe(reg.versions()[0]);
    // Task 7 owns graph state; until then the result must not expose any.
    expect(Object.keys(result).sort()).toEqual(['code', 'parent_version_id', 'status']);
    expect('edges' in result).toBe(false);
    expect('relations' in result).toBe(false);
  });

  test('A-3 cross-participant FORKED_FROM is accepted without inheritance', () => {
    const alice = participant('participant-a');
    const bob = participant('participant-b');
    const ancestor = descriptor({ id: 'iv-a-1', participant: 'participant-a', credentials: [credential('cred-a')] });
    const child = descriptor({
      id: 'iv-b-1',
      participant: 'participant-b',
      lineage: [link('iv-a-1', 'FORKED_FROM')],
    });
    const reg = registry([alice, bob], [ancestor, child]);
    const before = snapshot(reg);

    const result = validateDescriptor(child, reg);

    expect(result).toEqual({ status: 'VALID' });
    expect(snapshot(reg)).toBe(before);
    expect(ancestor.public_credentials.map((entry) => entry.credential_id)).toEqual(['cred-a']);
    expect(child.public_credentials).toEqual([]);
    expect(JSON.stringify(reg).toLowerCase()).not.toContain('grant');
  });

  test('A-4 FORKED_FROM cardinality violation is rejected and leaves Registry unchanged', () => {
    const alice = participant('participant-a');
    const firstParent = descriptor({ id: 'iv-a-1', participant: 'participant-a' });
    const secondParent = descriptor({ id: 'iv-a-2', participant: 'participant-a' });
    const child = descriptor({
      id: 'iv-a-3',
      participant: 'participant-a',
      lineage: [link('iv-a-1', 'FORKED_FROM'), link('iv-a-2', 'FORKED_FROM')],
    });
    const reg = registry([alice], [firstParent, secondParent, child]);
    const before = snapshot(reg);
    const childBefore = JSON.stringify(child);

    const result = validateDescriptor(child, reg);

    expectRejected(result, 'ERR_INVALID_CARDINALITY');
    expect(snapshot(reg)).toBe(before);
    expect(JSON.stringify(child)).toBe(childBefore);
  });

  test('A-5 valid MERGED_FROM is accepted without unioning credentials or authority', () => {
    const alice = participant('participant-a');
    const bob = participant('participant-b');
    const firstParent = descriptor({ id: 'iv-a-1', participant: 'participant-a', credentials: [credential('cred-a')] });
    const secondParent = descriptor({ id: 'iv-b-1', participant: 'participant-b', credentials: [credential('cred-b')] });
    const child = descriptor({
      id: 'iv-a-2',
      participant: 'participant-a',
      lineage: [link('iv-a-1', 'MERGED_FROM'), link('iv-b-1', 'MERGED_FROM')],
    });
    const reg = registry([alice, bob], [firstParent, secondParent, child]);
    const before = snapshot(reg);

    const result = validateDescriptor(child, reg);

    expect(result).toEqual({ status: 'VALID' });
    expect(snapshot(reg)).toBe(before);
    expect(firstParent.public_credentials.map((entry) => entry.credential_id)).toEqual(['cred-a']);
    expect(secondParent.public_credentials.map((entry) => entry.credential_id)).toEqual(['cred-b']);
    expect(child.public_credentials).toEqual([]);
    expect(JSON.stringify(reg).toLowerCase()).not.toContain('grant');
  });
});

