import { describe, expect, test } from 'bun:test';
import { validateIdentityVersionDescriptor } from '../../src/core/entities.js';
import { validateDescriptor } from '../../src/core/lineage.js';
import {
  credential,
  descriptor,
  expectRejected,
  link,
  participant,
  registry,
  snapshot,
} from '../support/fixtures.js';

const alice = participant('participant-a');
const bob = participant('participant-b');

const parentA1 = descriptor({ id: 'iv-a-1', participant: 'participant-a', credentials: [credential('cred-a')] });
const parentA2 = descriptor({ id: 'iv-a-2', participant: 'participant-a' });
const parentB1 = descriptor({ id: 'iv-b-1', participant: 'participant-b' });
const allParticipants = [alice, bob];
const allParents = [parentA1, parentA2, parentB1];

describe('cardinality per relation type', () => {
  test('CONTINUATION accepts zero or one parent and rejects two', () => {
    const none = descriptor({ id: 'iv-a-3', participant: 'participant-a' });
    const one = descriptor({ id: 'iv-a-3', participant: 'participant-a', lineage: [link('iv-a-1')] });
    const two = descriptor({
      id: 'iv-a-3',
      participant: 'participant-a',
      lineage: [link('iv-a-1'), link('iv-a-2')],
    });
    const reg = registry(allParticipants, allParents);

    expect(validateDescriptor(none, reg)).toEqual({ status: 'VALID' });
    expect(validateDescriptor(one, reg)).toEqual({ status: 'VALID' });
    expectRejected(validateDescriptor(two, reg), 'ERR_INVALID_CARDINALITY');
  });

  test('FORKED_FROM accepts zero or one parent and rejects two', () => {
    const none = descriptor({ id: 'iv-b-2', participant: 'participant-b' });
    const one = descriptor({ id: 'iv-b-2', participant: 'participant-b', lineage: [link('iv-a-1', 'FORKED_FROM')] });
    const two = descriptor({
      id: 'iv-b-2',
      participant: 'participant-b',
      lineage: [link('iv-a-1', 'FORKED_FROM'), link('iv-a-2', 'FORKED_FROM')],
    });
    const reg = registry(allParticipants, allParents);

    expect(validateDescriptor(none, reg)).toEqual({ status: 'VALID' });
    expect(validateDescriptor(one, reg)).toEqual({ status: 'VALID' });
    expectRejected(validateDescriptor(two, reg), 'ERR_INVALID_CARDINALITY');
  });

  test('MERGED_FROM requires at least two parents', () => {
    const none = descriptor({ id: 'iv-a-3', participant: 'participant-a' });
    const one = descriptor({ id: 'iv-a-3', participant: 'participant-a', lineage: [link('iv-a-1', 'MERGED_FROM')] });
    const two = descriptor({
      id: 'iv-a-3',
      participant: 'participant-a',
      lineage: [link('iv-a-1', 'MERGED_FROM'), link('iv-b-1', 'MERGED_FROM')],
    });
    const three = descriptor({
      id: 'iv-a-3',
      participant: 'participant-a',
      lineage: [
        link('iv-a-1', 'MERGED_FROM'),
        link('iv-a-2', 'MERGED_FROM'),
        link('iv-b-1', 'MERGED_FROM'),
      ],
    });
    const reg = registry(allParticipants, allParents);

    expect(validateDescriptor(none, reg)).toEqual({ status: 'VALID' });
    expectRejected(validateDescriptor(one, reg), 'ERR_INVALID_CARDINALITY');
    expect(validateDescriptor(two, reg)).toEqual({ status: 'VALID' });
    expect(validateDescriptor(three, reg)).toEqual({ status: 'VALID' });
  });

  test('mixed relation arrays are structurally legal', () => {
    const mixed = descriptor({
