const PARTICIPANT_KINDS: readonly ParticipantKind[] = [...];
const PARTICIPANT_FIELDS = ['id','kind','home_domain','registered_at'];
const RUNTIME_FIELDS = ['id','identity_version_id','execution_context_ref','ephemeral_public_key','instantiated_at'];
```

Validators:

```ts
export function validateParticipantRecord(value: unknown): Result<DeepReadonly<ParticipantRecord>> {
  const json = validateJsonValue(value);
  if (!json.ok) return json;
  const object = requireObject(json.value, '$');
  if (!object.ok) return object;
  const known = rejectUnknownFields(object.value, PARTICIPANT_FIELDS, '$');
  if (!known.ok) return known;
  const id = requireString(object.value.id, '$.id'); if (!id.ok) return id;
  const kind = requireEnum(object.value.kind, PARTICIPANT_KINDS, '$.kind'); if (!kind.ok) return kind;
  const domain = requireString(object.value.home_domain, '$.home_domain'); if (!domain.ok) return domain;
  const registered = requireTimestamp(object.value.registered_at, '$.registered_at'); if (!registered.ok) return registered;
  return { ok: true, value: deepFreeze({ id: id.value as ParticipantID, kind: kind.value, home_domain: domain.value as DomainID, registered_at: registered.value }) };
}
```

Note: `requireObject(json.value, '$')` — json.value is JsonValue. fine.

