export function evaluateBinding(state, binding, candidateID, policy, ctx): BindingResult {
  const candidate = state.descriptors.find(d => d.id === candidateID);
  if (candidate === undefined) return mechanism('E_UNKNOWN_BOUNDARY_REJECTED', 'Candidate descriptor not found');
  if (candidate.participant_id !== binding.target_participant_id) return {eligible:false, code:'ERR_AUTHORITY_BINDING_MISMATCH', details:{}};
  const compiled = compileSelector(binding.selector_expression, candidate.version_scheme);
  if (!compiled.ok) return mechanismFailureResult(compiled.error);
  const label = validateVersionLabel(candidate.version_label, candidate.version_scheme);
  if (!label.ok) return mechanismFailureResult(label.error);
  if (!selectorMatches(compiled.value, label.value)) return mismatch;
  const discovered = discoverPaths(state.graph, binding.traversal_scope, candidateID, binding.origin_version_id);
  if (!discovered.ok) return {eligible:false, code:'ERR_NO_TRAVERSAL_PATH', details:{}};
  const accepted: Path[] = [];
  const failed: FailedPath[] = [];
  for (const path of discovered.value) {
    const validation = validatePath(path, state.assessments, binding.assurance_requirement, policy, ctx);
    if (!validation.ok) return mechanismFailureResult(validation.error);
    if (validation.value.status === 'VALID') accepted.push(path);
    else failed.push({path, outcome: validation.value});
  }
  if (accepted.length > 0) return {eligible:true, acceptedPaths: Object.freeze(accepted)};
  if (failed.length === 0) return {eligible:false, code:'ERR_NO_TRAVERSAL_PATH', details:{}}; // shouldn't
  if (failed.every(f => f.outcome.status === 'CONTESTED')) return {eligible:false, kind:'CONTESTED', details:{perPath: failed}};
  // If any INVALID assurance => code assurance; if mixed contested+invalid -> code assurance (document aggregation)
  return {eligible:false, code:'ERR_ASSURANCE_PREDICATE_UNSATISFIED', details:{perPath: failed}};
}
