    const assessments = [
      assessmentRecord({ id: 'a-db', subject: 'iv-d', parents: ['iv-b'], relation: 'MERGED_FROM', verified: ['CONT_OK'] }),
      assessmentRecord({ id: 'a-dc', subject: 'iv-d', parents: ['iv-c'], relation: 'MERGED_FROM', verified: ['CONT_OK'] }),
      assessmentRecord({ id: 'a-ba', subject: 'iv-b', parents: ['iv-a-1'], relation: 'FORKED_FROM', verified: ['CONT_OK'] }),
      assessmentRecord({ id: 'a-ca', subject: 'iv-c', parents: ['iv-a-1'], relation: 'CONTINUATION', verified: ['CONT_OK'] }),
    ];
    const state = { graph, descriptors: [a, b, c, d], assessments };
    const binding = bindingFor({
