...
```

Reachability:
```ts
function canReachOrigin(graph, scope, originID): Set<IdentityVersionID> {
  const reverse = new Map<IdentityVersionID, IdentityVersionID[]>();
  for (const edge of graph.edges) {
    if (!relationAllowed(scope, edge.relation)) continue;
