export function validateMergeClosure(path, graph, assessments, requirement, policy, ctx): Result<MergeClosureResult> {
  const shape = validatePathShape(path);
  if (!shape.ok) return shape;

  const failures = new Map<string, MergeClosureBranchFailure>();
  for (const edge of path.edges) {
    if (edge.relation !== 'MERGED_FROM') continue;
    const parents = graph.edges
      .filter((candidate) => candidate.child === edge.child && candidate.relation === 'MERGED_FROM')
      .map((candidate) => edgeRef(candidate));
    // dedupe by parent
    const unique = new Map<string, EdgeRef>();
    for (const branch of parents) unique.set(String(branch.parent), branch);
    const sorted = [...unique.values()].sort((a,b)=> compareStrings(a.parent,b.parent));
    for (const branch of sorted) {
      if (branch.parent === edge.parent) continue;
      const key = `${String(branch.child)}\u0000${String(branch.parent)}`;
      if (failures.has(key)) continue;
      const applicable = assessEdge(branch, assessments, policy, ctx);
      if (!applicable.ok) return applicable;
      if (applicable.value.unresolved) { failures.set(key, {branch, reason:'NO_APPLICABLE_ASSESSMENT'}); continue; }
      const assurance = evaluateAssurance(applicable.value, requirement, policy, ctx);
      if ('kind' in assurance) return {ok:false,error:assurance};
      if (assurance.status === 'SATISFIED') continue;
      if (assurance.status === 'UNSATISFIED') failures.set(key,{branch,reason:'ASSURANCE_UNSATISFIED',missing:assurance.missing,disallowed:assurance.disallowed});
      else failures.set(key,{branch,reason:'CONTESTED',contestedClaims:assurance.contestedClaims});
    }
  }
  if (failures.size===0) return {ok:true, value: deepFreeze({status:'SATISFIED'}) as MergeClosureResult};
  const sorted = [...failures.values()].sort((a,b)=> compareStrings(a.branch.child,b.branch.child)||compareStrings(a.branch.parent,b.branch.parent));
  return {ok:true, value: deepFreeze({status:'UNSATISFIED', code:'ERR_MERGE_BRANCH_UNSATISFIED', failures: sorted}) as MergeClosureResult};
}
