  }

  const orderedFailures = [...failures.values()].sort(
    (a, b) =>
      compareStrings(a.branch.child, b.branch.child) || compareStrings(a.branch.parent, b.branch.parent),
  );
  return {
    ok: true,
    value: deepFreeze({
      status: 'UNSATISFIED',
      code: 'ERR_MERGE_BRANCH_UNSATISFIED',
      failures: orderedFailures,
    }) as MergeClosureResult,
  };
}

