function directMergeBranches(graph, child): EdgeRef[] {
  const branches = new Map<string, EdgeRef>();
  for (const candidate of graph.edges) {
    if (candidate.child === child && candidate.relation === 'MERGED_FROM') {
      branches.set(String(candidate.parent), edgeRef(candidate));
    }
  }
  return [...branches.values()].sort((a,b)=>compareStrings(a.parent,b.parent));
}
```

`evaluateClosureBranch`:
```ts
function evaluateClosureBranch(branch, assessments, requirement, policy, ctx): Result<MergeClosureBranchFailure | undefined> {
  const outcome = evaluateEdgeAssurance(...);
  if (!outcome.ok) return outcome;
  switch (outcome.value.status) {
    case 'SATISFIED': return {ok:true,value:undefined};
    case 'NO_APPLICABLE_ASSESSMENT': return {ok:true,value:{branch,reason:'NO_APPLICABLE_ASSESSMENT'}};
    case 'UNSATISFIED': return {ok:true,value:{branch,reason:'ASSURANCE_UNSATISFIED',missing:...,disallowed:...}};
    case 'CONTESTED': return {ok:true,value:{branch,reason:'CONTESTED',contestedClaims:...}};
  }
}
