490:   }
491: 
492:   for (const edge of path.edges) {
493:     const reference = edgeRef(edge);
494:     const outcome = evaluateEdgeAssurance(reference, assessments, requirement, policy, ctx);
495:     if (!outcome.ok) {
496:       return outcome;
497:     }
498: 
499:     if (outcome.value.status === 'SATISFIED') {
500:       continue;
501:     }
502:     if (outcome.value.status === 'NO_APPLICABLE_ASSESSMENT') {
503:       return validationValue({
504:         status: 'INVALID',
505:         code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
506:         edge: reference,
507:         missing: [...requirement.required_claims].sort(compareStrings),
508:         disallowed: [],
509:       });
510:     }
511:     if (outcome.value.status === 'UNSATISFIED') {
512:       return validationValue({
513:         status: 'INVALID',
514:         code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
515:         edge: reference,
516:         missing: outcome.value.missing,
517:         disallowed: outcome.value.disallowed,
518:       });
519:     }
520:     return validationValue({
521:       status: 'CONTESTED',
