185: function reachableToOrigin(
186:   graph: LineageGraph,
187:   scope: LineageTraversalScope,
188:   originID: IdentityVersionID,
189: ): ReadonlySet<IdentityVersionID> {
190:   const reverse = new Map<IdentityVersionID, IdentityVersionID[]>();
191:   for (const edge of graph.edges) {
192:     if (!relationAllowed(scope, edge.relation)) {
193:       continue;
194:     }
195:     // Duplicate entries are harmless: `reachable` prevents a node from being
196:     // queued twice, and total work stays linear in the number of edges.
197:     const children = reverse.get(edge.parent) ?? [];
198:     children.push(edge.child);
199:     reverse.set(edge.parent, children);
200:   }
201: 
202:   const reachable = new Set<IdentityVersionID>([originID]);
203:   const queue: IdentityVersionID[] = [originID];
204:   // A for...of array iterator observes elements appended during iteration,
205:   // which is what this BFS relies on.
206:   for (const node of queue) {
207:     for (const child of reverse.get(node) ?? []) {
208:       if (!reachable.has(child)) {
209:         reachable.add(child);
210:         queue.push(child);
211:       }
212:     }
213:   }
214:   return reachable;
215: }
216: 
217: function adjacencyFor(
218:   graph: LineageGraph,
219:   scope: LineageTraversalScope,
220:   reachable: ReadonlySet<IdentityVersionID>,
221: ): Map<IdentityVersionID, LineageEdge[]> {
222:   const adjacency = new Map<IdentityVersionID, LineageEdge[]>();
223: 
224:   for (const edge of graph.edges) {
225:     if (!relationAllowed(scope, edge.relation) || !reachable.has(edge.parent)) {
226:       continue;
227:     }
228:     const edges = adjacency.get(edge.child) ?? [];
229:     if (!edges.some((item) => item.parent === edge.parent && item.relation === edge.relation)) {
230:       edges.push({ child: edge.child, parent: edge.parent, relation: edge.relation });
231:     }
232:     adjacency.set(edge.child, edges);
233:   }
234: 
235:   for (const edges of adjacency.values()) {
236:     edges.sort((a, b) => compareStrings(a.parent, b.parent) || compareStrings(a.relation, b.relation));
237:   }
238:   return adjacency;
239: }
