    expect(perPath[0].path.edges.map((edge) => edge.relation)).toEqual(['FORKED_FROM']);
    expect(perPath[0].outcome).toEqual({ status: 'VALID' });
    expect(perPath[0].closure?.status).toBe('UNSATISFIED');
    if (perPath[0].closure?.status !== 'UNSATISFIED') return;
    expect(perPath[0].closure.failures.map((item) => String(item.branch.parent)).sort()).toEqual([
      'iv-b',
      'iv-c',
    ]);
  });
});

describe('FULL_ANCESTRY immediate closure consistency', () => {
  test('closure checks every direct parent edge and reports only the failing branches', () => {
    for (const scope of ['CONTINUATION_ONLY', 'FULL_ANCESTRY'] as const) {
      for (const missing of ['iv-b', 'iv-c', 'iv-e'] as const) {
        const state = multiParentState(missing);
        const result = evaluateBinding(
          state,
          scopeBinding(scope, 'iv-a-1', 'participant-a'),
          identityVersionId('iv-d'),
          EMPTY_POLICY,
          CTX,
        );

        const failure = expectNormativeFailure(result);
        expect(failure.code).toBe('ERR_MERGE_BRANCH_UNSATISFIED');
        const perPath = failure.details.perPath ?? [];
        expect(perPath).toHaveLength(1);
        expect(perPath[0].outcome).toEqual({ status: 'VALID' });
        expect(perPath[0].closure?.status).toBe('UNSATISFIED');
        if (perPath[0].closure?.status !== 'UNSATISFIED') return;

        expect(perPath[0].closure.failures).toHaveLength(1);
        expect(String(perPath[0].closure.failures[0].branch.parent)).toBe(missing);
        expect(perPath[0].closure.failures[0].reason).toBe('NO_APPLICABLE_ASSESSMENT');
      }
    }
  });

  test('a merge node whose parent branches all pass has a satisfied closure', () => {
    const state = multiParentState();

    for (const scope of ['CONTINUATION_ONLY', 'FULL_ANCESTRY'] as const) {
      const result = evaluateBinding(
        state,
        scopeBinding(scope, 'iv-a-1', 'participant-a'),
        identityVersionId('iv-d'),
        EMPTY_POLICY,
        CTX,
      );

      expect(result.eligible).toBe(true);
      if (!result.eligible) continue;
      expect(result.details.perPath).toHaveLength(1);
      expect(result.details.perPath[0].outcome).toEqual({ status: 'VALID' });
      expect(result.details.perPath[0].closure).toEqual({ status: 'SATISFIED' });
    }
  });

  test('closure reports only immediate branches, never recursive ones', () => {
    const state = mergeClosureState();
    const result = evaluateBinding(
      state,
      scopeBinding('FULL_ANCESTRY', 'iv-a-1', 'participant-d'),
      identityVersionId('iv-d'),
      EMPTY_POLICY,
      CTX,
    );

    const failure = expectNormativeFailure(result);
    expect(failure.code).toBe('ERR_MERGE_BRANCH_UNSATISFIED');
    const perPath = failure.details.perPath ?? [];
    const survived = perPath.find((item) => item.outcome.status === 'VALID');
    expect(survived?.closure?.status).toBe('UNSATISFIED');
    if (survived?.closure?.status !== 'UNSATISFIED') return;

    expect(survived.closure.failures).toHaveLength(1);
    expect(String(survived.closure.failures[0].branch.parent)).toBe('iv-b');
    expect(survived.closure.failures.some((item) => String(item.branch.parent) === 'iv-a-1')).toBe(false);
  });
});

describe('bounded mixed-relation enumeration', () => {
  const entryRelations: readonly EntryRelation[] = ['CONTINUATION', 'FORKED_FROM'];
  const parentRelations: readonly MergeRelation[] = ['CONTINUATION', 'FORKED_FROM', 'MERGED_FROM'];

  test('discovery stays scope-permitted and closure stays scope-independent across 18 graphs', () => {
    for (const entryRelation of entryRelations) {
      for (const parentBRelation of parentRelations) {
        for (const parentCRelation of parentRelations) {
          const state = mixedState({ entryRelation, parentBRelation, parentCRelation });
          const targetParticipant = entryRelation === 'CONTINUATION' ? 'participant-a' : 'participant-d';

          for (const scope of SCOPES) {
            const result = evaluateBinding(
              state,
              scopeBinding(scope, 'iv-a-1', targetParticipant),
              identityVersionId('iv-d'),
              EMPTY_POLICY,
              CTX,
            );
            const entryAllowed = scope === 'FULL_ANCESTRY' || entryRelation === 'CONTINUATION' || scope === 'CONTINUATION_AND_FORK';

            if (!entryAllowed) {
              const failure = expectNormativeFailure(result);
              expect(failure.code).toBe('ERR_NO_TRAVERSAL_PATH');
              continue;
            }

            const mergeParentPresent = parentBRelation === 'MERGED_FROM' || parentCRelation === 'MERGED_FROM';
            if (mergeParentPresent) {
              const failure = expectNormativeFailure(result);
              expect(failure.code).toBe('ERR_MERGE_BRANCH_UNSATISFIED');
              const perPath = failure.details.perPath ?? [];
              expect(perPath).toHaveLength(1);
              expect(perPath[0].outcome).toEqual({ status: 'VALID' });
              expect(perPath[0].path.edges.map((edge) => edge.relation)).toEqual([entryRelation]);
              expect(perPath[0].closure?.status).toBe('UNSATISFIED');
              if (perPath[0].closure?.status !== 'UNSATISFIED') return;
              expect(perPath[0].closure.failures.map((item) => String(item.branch.parent)).sort()).toEqual([
                'iv-b',
                'iv-c',
              ]);
              expect(perPath[0].closure.failures.map((item) => item.branch.relation).sort()).toEqual(
                [parentBRelation, parentCRelation].sort(),
              );
            } else {
              expect(result.eligible).toBe(true);
              if (!result.eligible) continue;
              expect(perPathOf(result)).toHaveLength(1);
              expect(perPathOf(result)[0].closure).toEqual({ status: 'SATISFIED' });
            }
          }
        }
      }
    }
  });
});

import { expect, test } from 'bun:test';
import { buildLineageGraph } from '../../src/core/lineage.js';
import { discoverPaths, evaluateBinding } from '../../src/core/traversal.js';
import { identityVersionId } from '../../src/core/primitives.js';
import { descriptor, link, participant, registry } from '../support/fixtures.js';
import { CTX, EMPTY_POLICY, assessmentRecord, bindingFor } from '../support/traversal.js';

// BLOCKED / NON-CONFORMANCE (A-11).
//
// CORE-001 §8.6 says a selected path that «проходит через» a MERGED_FROM node
// must close all of that node's parent edges. It does not define whether the
// terminal origin node counts as a node the path "passes through".
//
// The current implementation walks path edges and closes `edge.child`. The
// terminal origin is never a child, so its parent branches are not closed.
// This file pins that actual behavior; it is excluded from §12 conformance.

test('BLOCKED (A-11, non-conformance): a MERGED_FROM origin is not closed', () => {
  const alice = participant('participant-a');
  const bob = participant('participant-b');
  const carol = participant('participant-c');
  const p1 = descriptor({ id: 'iv-p1', participant: 'participant-b' });
  const p2 = descriptor({ id: 'iv-p2', participant: 'participant-c' });
  const origin = descriptor({
    id: 'iv-o',
    participant: 'participant-a',
    versionLabel: '2.0.0',
    lineage: [link('iv-p1', 'MERGED_FROM'), link('iv-p2', 'MERGED_FROM')],
  });
  const candidate = descriptor({
    id: 'iv-c',
    participant: 'participant-a',
    versionLabel: '3.0.0',
    lineage: [link('iv-o', 'CONTINUATION')],
  });
  const graph = buildLineageGraph(registry([alice, bob, carol], [p1, p2, origin, candidate]));
  const assessments = [
    assessmentRecord({
      id: 'c-o',
      subject: 'iv-c',
      parents: ['iv-o'],
      relation: 'CONTINUATION',
      verified: ['OK'],
    }),
  ];
  const binding = bindingFor({
    origin: 'iv-o',
    selector: '>=1.0.0',
    scope: 'FULL_ANCESTRY',
    claims: ['OK'],
    targetParticipant: 'participant-a',
  });

  const discovered = discoverPaths(
    graph,
    'FULL_ANCESTRY',
    identityVersionId('iv-c'),
    identityVersionId('iv-o'),
  );
  expect(discovered.ok).toBe(true);
  if (!discovered.ok) return;
  expect(discovered.value).toHaveLength(1);
  expect(discovered.value[0].edges.map((edge) => edge.relation)).toEqual(['CONTINUATION']);

  const result = evaluateBinding(
    { graph, descriptors: [p1, p2, origin, candidate], assessments },
    binding,
    identityVersionId('iv-c'),
    EMPTY_POLICY,
    CTX,
  );
  expect(result.eligible).toBe(true);
  if (!result.eligible) return;
  expect(result.details.perPath).toHaveLength(1);
  const outcome = result.details.perPath[0];
  expect(outcome.outcome).toEqual({ status: 'VALID' });

  // Closure runs for every VALID path. SATISFIED here means no merge node was
  // found among the path's edge children; it does not mean O's parents passed.
  expect(outcome.closure).toEqual({ status: 'SATISFIED' });

  const originBranches = graph.edges.filter((edge) => edge.child === identityVersionId('iv-o'));
  expect(originBranches.map((edge) => String(edge.parent)).sort()).toEqual(['iv-p1', 'iv-p2']);
  expect(assessments.some((record) => record.subject_version_id === identityVersionId('iv-o'))).toBe(false);
});

test.todo('BLOCKED (A-11, non-conformance): if §8.6 includes the terminal origin, O→P1 and O→P2 would be closed');

