  'conflict',
);

const nodeChoiceArbitrary: fc.Arbitrary<NodeChoice> = fc.record({
  cont: fc.option(fc.nat({ max: 50 }), { nil: null }),
  fork: fc.option(fc.nat({ max: 50 }), { nil: null }),
  merges: fc.array(fc.nat({ max: 50 }), { maxLength: 4 }),
});

/**
 * General bounded DAG generator. Edges always point to a lower node index, so
 * the graph is acyclic by construction. CONTINUATION parents constrain the
 * child's participant, matching §5.2. MERGED_FROM parents are distinct.
 */
export const dagSpecArbitrary: fc.Arbitrary<DagSpec> = fc.integer({ min: 2, max: 7 }).chain((nodeCount) =>
  fc.record({
    nodeCount: fc.constant(nodeCount),
    originIndex: fc.integer({ min: 0, max: nodeCount - 2 }),
    scope: fc.constantFrom(...SCOPES),
    participants: fc.array(fc.integer({ min: 0, max: PARTICIPANTS.length - 1 }), {
      minLength: nodeCount,
      maxLength: nodeCount,
    }),
    choices: fc.array(nodeChoiceArbitrary, { minLength: nodeCount, maxLength: nodeCount }),
    modes: fc.array(modeArbitrary, { minLength: 1, maxLength: 12 }),
    conflictPolicy: fc.boolean(),
  }),
);

function nodeId(index: number): string {
  return `iv-v${index}`;
}

function uniqueIndices(values: readonly number[], bound: number): number[] {
  return [...new Set(values.map((value) => value % bound))];
}

function buildLineage(
  index: number,
  choice: NodeChoice,
  participants: readonly string[],
): { lineage: ReturnType<typeof link>[]; participant: string } {
  const contIndex = choice.cont === null ? null : choice.cont % index;
  const forkIndex = choice.fork === null ? null : choice.fork % index;
  const mergeIndices = uniqueIndices(choice.merges, index).filter(
    (parent) => parent !== contIndex && parent !== forkIndex,
  );
  const mergeParents = mergeIndices.length >= 2 ? mergeIndices.slice(0, 3) : [];

  const lineage: ReturnType<typeof link>[] = [];
  if (contIndex !== null) {
    lineage.push(link(nodeId(contIndex), 'CONTINUATION'));
  }
  if (forkIndex !== null) {
    lineage.push(link(nodeId(forkIndex), 'FORKED_FROM'));
  }
  for (const parent of mergeParents) {
    lineage.push(link(nodeId(parent), 'MERGED_FROM'));
  }

  const participantId =
    contIndex === null ? (participants[index] as string) : (participants[contIndex] as string);
  return { lineage, participant: participantId };
}

function assessmentFor(
  edgeIndex: number,
  mode: AssessmentMode,
  edge: { readonly child: string; readonly parent: string; readonly relation: 'CONTINUATION' | 'FORKED_FROM' | 'MERGED_FROM' },
): ContinuityAssessment[] {
  if (mode === 'none') {
    return [];
  }
  if (mode === 'conflict') {
    return [
      assessmentRecord({
        id: `a-${edgeIndex}-1`,
        subject: edge.child,
        parents: [edge.parent],
        relation: edge.relation,
        verified: ['OK'],
      }),
      assessmentRecord({
        id: `a-${edgeIndex}-2`,
        subject: edge.child,
        parents: [edge.parent],
        relation: edge.relation,
        unverified: ['OK'],
      }),
    ];
  }
  if (mode === 'unverified') {
    return [
      assessmentRecord({
        id: `a-${edgeIndex}`,
        subject: edge.child,
        parents: [edge.parent],
        relation: edge.relation,
        unverified: ['OK'],
      }),
    ];
  }
  if (mode === 'wrong') {
    return [
      assessmentRecord({
        id: `a-${edgeIndex}`,
        subject: edge.child,
        parents: [edge.parent],
        relation: edge.relation,
        verified: ['OTHER'],
      }),
    ];
  }
  return [
    assessmentRecord({
      id: `a-${edgeIndex}`,
      subject: edge.child,
      parents: [edge.parent],
      relation: edge.relation,
      verified: ['OK'],
      by: mode === 'untrusted' ? 'untrusted.org' : 'domain-a',
    }),
  ];
}

/** Builds a validated graph, descriptors, assessments and binding from a spec. */
export function buildCase(spec: DagSpec): GeneratedCase {
  const participants: string[] = [];
  const descriptors: ReturnType<typeof descriptor>[] = [];
  const participantRecords = PARTICIPANTS.map((id) => participant(id));

  for (let index = 0; index < spec.nodeCount; index += 1) {
    const chosen = PARTICIPANTS[(spec.participants[index] as number) % PARTICIPANTS.length] as string;
    if (index === 0) {
      participants.push(chosen);
      descriptors.push(descriptor({ id: nodeId(index), participant: chosen, versionLabel: '1.0.0' }));
      continue;
    }

    const built = buildLineage(index, spec.choices[index] as NodeChoice, participants);
    participants.push(built.participant);
    descriptors.push(
      descriptor({
        id: nodeId(index),
        participant: built.participant,
        versionLabel: '1.0.0',
        lineage: built.lineage,
      }),
    );
  }

  const registryValue: Registry = registry(participantRecords, descriptors);
  for (const value of descriptors) {
    const validation = validateDescriptor(value, registryValue);
    if (validation.status !== 'VALID') {
      throw new Error(`generator produced an invalid descriptor: ${validation.code}`);
    }
  }

  const graph = buildGraph(registryValue);
  const assessments: ContinuityAssessment[] = [];
  graph.edges.forEach((edge, index) => {
    const mode = (spec.modes[index % spec.modes.length] as AssessmentMode) ?? 'none';
    assessments.push(
      ...assessmentFor(index, mode, {
        child: String(edge.child),
        parent: String(edge.parent),
        relation: edge.relation,
      }),
    );
  });

  const candidateIndex = spec.nodeCount - 1;
  const candidate = identityVersionId(nodeId(candidateIndex));
  const origin = identityVersionId(nodeId(spec.originIndex));
  const binding = bindingFor({
    origin: nodeId(spec.originIndex),
    selector: '>=1.0.0',
    scope: spec.scope,
    claims: ['OK'],
    targetParticipant: participants[candidateIndex] as string,
  });

  return {
    spec,
    graph,
    descriptors,
    assessments,
    binding,
    candidate,
    origin,
    policy: spec.conflictPolicy ? { conflictPredicate: () => true } : EMPTY_POLICY,
    ctx: CTX,
  };
}

import { buildLineageGraph } from '../../src/core/lineage.js';
import { identityVersionId } from '../../src/core/primitives.js';

function buildGraph(registryValue: Registry): LineageGraph {
  return buildLineageGraph(registryValue);
}

/** Fixed seven-node shape: mixed relations and a nested merge inside a closure branch. */
export function mixedMergeSpec(
  scope: LineageTraversalScope,
  modes: readonly AssessmentMode[],
  conflictPolicy: boolean,
): DagSpec {
  return {
    nodeCount: 7,
    originIndex: 0,
    scope,
    participants: [0, 1, 2, 3, 0, 1, 2],
    choices: [
      { cont: null, fork: null, merges: [] },
      { cont: null, fork: null, merges: [] },
      { cont: null, fork: null, merges: [] },
      { cont: null, fork: null, merges: [1, 2] },
      { cont: null, fork: null, merges: [] },
      { cont: 0, fork: 6, merges: [3, 4] },
      { cont: null, fork: null, merges: [] },
    ],
    modes,
    conflictPolicy,
  };
}

/** Fixed diamond: D MERGED_FROM B,C; B FORKED_FROM A; C CONTINUATION A. */
export function diamondSpec(
  scope: LineageTraversalScope,
  modes: readonly AssessmentMode[],
  conflictPolicy: boolean,
): DagSpec {
  return {
    nodeCount: 4,
    originIndex: 0,
    scope,
    participants: [0, 1, 0, 3],
    choices: [
      { cont: null, fork: null, merges: [] },
      { cont: null, fork: 0, merges: [] },
      { cont: 0, fork: null, merges: [] },
      { cont: null, fork: null, merges: [1, 2] },
    ],
    modes,
    conflictPolicy,
  };
}

export const mixedMergeCaseArbitrary: fc.Arbitrary<GeneratedCase> = fc
  .record({
    scope: fc.constantFrom(...SCOPES),
    modes: fc.array(modeArbitrary, { minLength: 6, maxLength: 6 }),
    conflictPolicy: fc.boolean(),
  })
  .map((input) => buildCase(mixedMergeSpec(input.scope, input.modes, input.conflictPolicy)));

export const diamondCaseArbitrary: fc.Arbitrary<GeneratedCase> = fc
  .record({
    modes: fc.array(modeArbitrary, { minLength: 4, maxLength: 4 }),
    conflictPolicy: fc.boolean(),
  })
  .map((input) => buildCase(diamondSpec('FULL_ANCESTRY', input.modes, input.conflictPolicy)));

export interface ShapeStats {
  readonly mergeNodes: number;
  readonly mixedRelationNodes: number;
  readonly closureOnlyBranches: number;
  readonly hasCycle: boolean;
}

/** Structural coverage counters used to report what the generator actually produced. */
export function shapeStats(graph: LineageGraph): ShapeStats {
  const parentsByChild = new Map<string, { relation: string; parent: string }[]>();
  for (const edge of graph.edges) {
    const list = parentsByChild.get(String(edge.child)) ?? [];
    list.push({ relation: edge.relation, parent: String(edge.parent) });
    parentsByChild.set(String(edge.child), list);
  }

  let mergeNodes = 0;
  let mixedRelationNodes = 0;
  let closureOnlyBranches = 0;

  for (const parents of parentsByChild.values()) {
    if (!parents.some((parent) => parent.relation === 'MERGED_FROM')) {
      continue;
    }
    mergeNodes += 1;
    if (new Set(parents.map((parent) => parent.relation)).size > 1) {
      mixedRelationNodes += 1;
    }
    for (const parent of parents) {
      if ((parentsByChild.get(parent.parent) ?? []).length > 0) {
        closureOnlyBranches += 1;
      }
    }
  }

  return {
    mergeNodes,
    mixedRelationNodes,
    closureOnlyBranches,
    hasCycle: graph.cycles.length > 0,
  };
}

/**
 * Independent brute-force reference model for the IMMEDIATE-closure contract.
 *
 * Independence boundary:
 * - This module NEVER calls `discoverPaths`, `validatePath`,
 *   `validateMergeClosure` or `evaluateBinding`.
 * - It reuses only Task 8 assessment primitives (`assessEdge`,
 *   `evaluateAssurance`) so that policy/trust semantics are not re-implemented.
 * - Path enumeration, closure-branch selection and top-level aggregation are
 *   implemented here from the graph edges.
 *
 * Boundaries kept explicit:
 * - DAG only: cyclic graphs are rejected by the oracle and tested separately.
 * - Immediate closure only: closure-only branches are never recursed (A-5).
 * - The terminal origin is never an `edge.child`, so it is not closed (A-11).
 * - Aggregation follows current implementation behavior; this does not resolve
 *   the normative precedence question A-8.
 */
import type { ContinuityAssessment, ContinuityAssuranceRequirement, EdgeRef, Policy } from '../../../src/core/assessment.js';
import { assessEdge, evaluateAssurance } from '../../../src/core/assessment.js';
import type { LineageGraph } from '../../../src/core/lineage.js';
import type { IdentityVersionID } from '../../../src/core/primitives.js';
import type { TemporalContext } from '../../../src/core/temporal.js';
import type { ConditionalVersionBinding, LineageTraversalScope } from '../../../src/core/traversal.js';

export type Relation = 'CONTINUATION' | 'FORKED_FROM' | 'MERGED_FROM';
export type EdgeTriple = readonly [string, string, Relation];

export interface NormalizedFailure {
  readonly branch: EdgeTriple;
  readonly reason: 'NO_APPLICABLE_ASSESSMENT' | 'ASSURANCE_UNSATISFIED' | 'CONTESTED';
  readonly missing?: readonly string[];
  readonly disallowed?: readonly string[];
  readonly contestedClaims?: readonly string[];
}

export interface NormalizedPath {
  readonly key: string;
  readonly scope: string;
  readonly edges: readonly EdgeTriple[];
  readonly outcome: {
    readonly status: string;
    readonly code?: string;
    readonly missing?: readonly string[];
    readonly disallowed?: readonly string[];
    readonly contestedClaims?: readonly string[];
  };
  readonly closure?: {
    readonly status: string;
    readonly code?: string;
    readonly failures?: readonly NormalizedFailure[];
  };
}

export type NormalizedResult =
  | { readonly kind: 'eligible'; readonly accepted: readonly string[]; readonly perPath: readonly NormalizedPath[] }
  | { readonly kind: 'no-path' }
  | { readonly kind: 'failure'; readonly code: string; readonly perPath: readonly NormalizedPath[] }
  | { readonly kind: 'contested'; readonly perPath: readonly NormalizedPath[] }
  | { readonly kind: 'mechanism'; readonly message: string };

export interface OracleInput {
  readonly graph: LineageGraph;
  readonly binding: ConditionalVersionBinding;
  readonly candidate: IdentityVersionID;
  readonly assessments: readonly ContinuityAssessment[];
  readonly policy: Policy;
  readonly ctx: TemporalContext;
}

export type OracleResult = { readonly ok: true; readonly result: NormalizedResult } | { readonly ok: false; readonly error: string };

interface SimpleEdge {
  readonly child: IdentityVersionID;
  readonly parent: IdentityVersionID;
  readonly relation: Relation;
}

interface EdgeAssessment {
  readonly status: 'SATISFIED' | 'NO_APPLICABLE' | 'UNSATISFIED' | 'CONTESTED';
  readonly missing?: readonly string[];
  readonly disallowed?: readonly string[];
  readonly contestedClaims?: readonly string[];
}

type EdgeEvaluation = { readonly ok: true; readonly value: EdgeAssessment } | { readonly ok: false; readonly error: string };

function compareStrings(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function permitted(scope: LineageTraversalScope, relation: Relation): boolean {
  if (scope === 'CONTINUATION_ONLY') {
    return relation === 'CONTINUATION';
  }
  if (scope === 'CONTINUATION_AND_FORK') {
    return relation === 'CONTINUATION' || relation === 'FORKED_FROM';
  }
  return true;
}

function triple(edge: SimpleEdge): EdgeTriple {
  return [String(edge.child), String(edge.parent), edge.relation];
}

function edgeKey(edge: SimpleEdge): string {
  return triple(edge).join('\u0000');
}

export function pathKey(scope: string, edges: readonly EdgeTriple[]): string {
  return JSON.stringify({ scope, edges });
}

function sortedEdges(edges: readonly SimpleEdge[]): SimpleEdge[] {
  return [...edges].sort(
    (left, right) =>
      compareStrings(String(left.child), String(right.child)) ||
      compareStrings(String(left.parent), String(right.parent)) ||
      compareStrings(left.relation, right.relation),
  );
}

/** Exhaustive DFS over scope-permitted simple paths from candidate to origin. */
function enumeratePaths(
  graph: LineageGraph,
  scope: LineageTraversalScope,
  candidate: IdentityVersionID,
  origin: IdentityVersionID,
): SimpleEdge[][] {
  const outbound = new Map<string, SimpleEdge[]>();
  for (const edge of graph.edges) {
    if (!permitted(scope, edge.relation)) {
      continue;
    }
    const key = String(edge.child);
    const list = outbound.get(key) ?? [];
    list.push({ child: edge.child, parent: edge.parent, relation: edge.relation });
    outbound.set(key, list);
  }
  for (const list of outbound.values()) {
    list.sort(
      (left, right) =>
        compareStrings(String(left.parent), String(right.parent)) ||
        compareStrings(left.relation, right.relation),
    );
  }

  if (candidate === origin) {
    return [];
  }

  const paths: SimpleEdge[][] = [];
  const visited = new Set<string>([String(candidate)]);
  const stack: SimpleEdge[] = [];

  const walk = (node: IdentityVersionID): void => {
    if (node === origin) {
      paths.push([...stack]);
      return;
    }
    for (const edge of outbound.get(String(node)) ?? []) {
      const parentKey = String(edge.parent);
      if (visited.has(parentKey)) {
        continue;
      }
      visited.add(parentKey);
      stack.push(edge);
      walk(edge.parent);
      stack.pop();
      visited.delete(parentKey);
    }
  };

  walk(candidate);
  return paths.sort((left, right) => compareStrings(pathKey(scope, left.map(triple)), pathKey(scope, right.map(triple))));
}

function evaluateEdge(
  edge: SimpleEdge,
  assessments: readonly ContinuityAssessment[],
  requirement: ContinuityAssuranceRequirement,
  policy: Policy,
  ctx: TemporalContext,
): EdgeEvaluation {
  const reference: EdgeRef = edge;
  const applicable = assessEdge(reference, assessments, policy, ctx);
  if (!applicable.ok) {
    return { ok: false, error: applicable.error.message };
  }
  if (applicable.value.unresolved) {
    return {
      ok: true,
      value: {
        status: 'NO_APPLICABLE',
        missing: [...requirement.required_claims].sort(compareStrings),
        disallowed: [],
      },
    };
  }

  const assurance = evaluateAssurance(applicable.value, requirement, policy, ctx);
  if ('kind' in assurance) {
    return { ok: false, error: assurance.message };
  }
  if (assurance.status === 'SATISFIED') {
    return { ok: true, value: { status: 'SATISFIED' } };
  }
  if (assurance.status === 'UNSATISFIED') {
    return {
      ok: true,
      value: { status: 'UNSATISFIED', missing: assurance.missing, disallowed: assurance.disallowed },
    };
  }
  return { ok: true, value: { status: 'CONTESTED', contestedClaims: assurance.contestedClaims } };
}

function directParents(graph: LineageGraph, child: IdentityVersionID): SimpleEdge[] {
  const seen = new Set<string>();
  const parents: SimpleEdge[] = [];
  for (const edge of graph.edges) {
    if (edge.child !== child) {
      continue;
    }
    const key = edgeKey(edge);
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    parents.push({ child: edge.child, parent: edge.parent, relation: edge.relation });
  }
  return sortedEdges(parents);
}

function validateOnePath(
  path: readonly SimpleEdge[],
  graph: LineageGraph,
  requirement: ContinuityAssuranceRequirement,
  assessments: readonly ContinuityAssessment[],
  policy: Policy,
  ctx: TemporalContext,
): { readonly ok: true; readonly outcome: NormalizedPath['outcome']; readonly closure?: NormalizedPath['closure'] } | { readonly ok: false; readonly error: string } {
  for (const edge of path) {
    const evaluation = evaluateEdge(edge, assessments, requirement, policy, ctx);
    if (!evaluation.ok) {
      return evaluation;
    }
    if (evaluation.value.status === 'SATISFIED') {
      continue;
    }
    if (evaluation.value.status === 'NO_APPLICABLE') {
      return {
        ok: true,
        outcome: {
          status: 'INVALID',
          code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
          missing: evaluation.value.missing,
          disallowed: evaluation.value.disallowed,
        },
      };
    }
    if (evaluation.value.status === 'UNSATISFIED') {
      return {
        ok: true,
        outcome: {
          status: 'INVALID',
          code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
          missing: evaluation.value.missing,
          disallowed: evaluation.value.disallowed,
        },
      };
    }
    return {
      ok: true,
      outcome: { status: 'CONTESTED', contestedClaims: evaluation.value.contestedClaims },
    };
  }

  const closure = immediateClosure(path, graph, requirement, assessments, policy, ctx);
  if (!closure.ok) {
    return closure;
  }
  return { ok: true, outcome: { status: 'VALID' }, closure: closure.closure };
}

/**
 * Immediate closure: for every path edge whose child is a merge node, check all
 * direct parent edges except the exact path edge. No recursion.
 */
function immediateClosure(
  path: readonly SimpleEdge[],
  graph: LineageGraph,
  requirement: ContinuityAssuranceRequirement,
  assessments: readonly ContinuityAssessment[],
  policy: Policy,
  ctx: TemporalContext,
): { readonly ok: true; readonly closure: NormalizedPath['closure'] } | { readonly ok: false; readonly error: string } {
  const failures = new Map<string, NormalizedFailure>();

  for (const edge of path) {
    const parents = directParents(graph, edge.child);
    if (!parents.some((parent) => parent.relation === 'MERGED_FROM')) {
      continue;
    }
    for (const branch of parents) {
      if (branch.parent === edge.parent && branch.relation === edge.relation) {
        continue;
      }
      const key = edgeKey(branch);
      if (failures.has(key)) {
        continue;
      }
      const evaluation = evaluateEdge(branch, assessments, requirement, policy, ctx);
      if (!evaluation.ok) {
        return evaluation;
      }
      if (evaluation.value.status === 'SATISFIED') {
        continue;
      }
      if (evaluation.value.status === 'NO_APPLICABLE') {
        failures.set(key, { branch: triple(branch), reason: 'NO_APPLICABLE_ASSESSMENT' });
      } else if (evaluation.value.status === 'UNSATISFIED') {
        failures.set(key, {
          branch: triple(branch),
          reason: 'ASSURANCE_UNSATISFIED',
          missing: evaluation.value.missing,
          disallowed: evaluation.value.disallowed,
        });
      } else {
        failures.set(key, {
          branch: triple(branch),
          reason: 'CONTESTED',
          contestedClaims: evaluation.value.contestedClaims,
        });
      }
    }
  }

  const ordered = [...failures.values()].sort(
    (left, right) =>
      compareStrings(left.branch[0], right.branch[0]) ||
      compareStrings(left.branch[1], right.branch[1]) ||
      compareStrings(left.branch[2], right.branch[2]),
  );
  return ordered.length === 0
    ? { ok: true, closure: { status: 'SATISFIED' } }
    : {
        ok: true,
        closure: { status: 'UNSATISFIED', code: 'ERR_MERGE_BRANCH_UNSATISFIED', failures: ordered },
      };
}

/**
 * Brute-force immediate-closure reference.
 *
 * Aggregation mirrors the current implementation: fully accepted path wins;
 * then closure failure, cycle, contested, assurance. This is implementation
 * behavior used to detect regressions; A-8 remains OPEN.
 */
export function runOracle(input: OracleInput): OracleResult {
  const { graph, binding, candidate, assessments, policy, ctx } = input;

  if (graph.cycles.length > 0) {
    return { ok: false, error: 'oracle is DAG-only; cyclic graph passed to the immediate-closure oracle' };
  }

  const paths = enumeratePaths(graph, binding.traversal_scope, candidate, binding.origin_version_id);
  const perPath: NormalizedPath[] = [];
  for (const path of paths) {
    const evaluated = validateOnePath(path, graph, binding.assurance_requirement, assessments, policy, ctx);
    if (!evaluated.ok) {
      return evaluated;
    }
    const edges = path.map(triple);
    perPath.push({
      key: pathKey(binding.traversal_scope, edges),
      scope: binding.traversal_scope,
      edges,
      outcome: evaluated.outcome,
      ...(evaluated.closure === undefined ? {} : { closure: evaluated.closure }),
    });
  }

  const accepted = perPath
    .filter((item) => item.outcome.status === 'VALID' && item.closure?.status === 'SATISFIED')
    .map((item) => item.key)
    .sort(compareStrings);
  if (accepted.length > 0) {
    return { ok: true, result: { kind: 'eligible', accepted, perPath } };
  }
  if (paths.length === 0) {
    return { ok: true, result: { kind: 'no-path' } };
  }
  if (perPath.some((item) => item.closure?.status === 'UNSATISFIED')) {
    return { ok: true, result: { kind: 'failure', code: 'ERR_MERGE_BRANCH_UNSATISFIED', perPath } };
  }
  if (perPath.some((item) => item.outcome.status === 'CONTESTED')) {
    return { ok: true, result: { kind: 'contested', perPath } };
  }
  return {
    ok: true,
    result: { kind: 'failure', code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED', perPath },
  };
}

/**
 * Independent brute-force reference model for the IMMEDIATE-closure contract.
 *
 * Independence boundary:
 * - This module NEVER calls `discoverPaths`, `validatePath`,
 *   `validateMergeClosure` or `evaluateBinding`.
 * - It reuses only Task 8 assessment primitives (`assessEdge`,
 *   `evaluateAssurance`) so that policy/trust semantics are not re-implemented.
 * - Path enumeration, closure-branch selection and top-level aggregation are
 *   implemented here from the graph edges.
 *
 * Boundaries kept explicit:
 * - DAG only: cyclic graphs are rejected by the oracle and tested separately.
 * - Immediate closure only: closure-only branches are never recursed (A-5).
 * - The terminal origin is never an `edge.child`, so it is not closed (A-11).
 * - Aggregation follows current implementation behavior; this does not resolve
 *   the normative precedence question A-8.
 */
import type { ContinuityAssessment, ContinuityAssuranceRequirement, EdgeRef, Policy } from '../../../src/core/assessment.js';
import { assessEdge, evaluateAssurance } from '../../../src/core/assessment.js';
import type { LineageGraph } from '../../../src/core/lineage.js';
import type { IdentityVersionID } from '../../../src/core/primitives.js';
import type { TemporalContext } from '../../../src/core/temporal.js';
import type { ConditionalVersionBinding, LineageTraversalScope } from '../../../src/core/traversal.js';

export type Relation = 'CONTINUATION' | 'FORKED_FROM' | 'MERGED_FROM';
export type EdgeTriple = readonly [string, string, Relation];

export interface NormalizedFailure {
  readonly branch: EdgeTriple;
  readonly reason: 'NO_APPLICABLE_ASSESSMENT' | 'ASSURANCE_UNSATISFIED' | 'CONTESTED';
  readonly missing?: readonly string[];
  readonly disallowed?: readonly string[];
  readonly contestedClaims?: readonly string[];
}

export interface NormalizedPath {
  readonly key: string;
  readonly scope: string;
  readonly edges: readonly EdgeTriple[];
  readonly outcome: {
    readonly status: string;
    readonly code?: string;
    readonly missing?: readonly string[];
    readonly disallowed?: readonly string[];
    readonly contestedClaims?: readonly string[];
  };
  readonly closure?: {
    readonly status: string;
    readonly code?: string;
    readonly failures?: readonly NormalizedFailure[];
  };
}

export type NormalizedResult =
  | { readonly kind: 'eligible'; readonly accepted: readonly string[]; readonly perPath: readonly NormalizedPath[] }
  | { readonly kind: 'no-path' }
  | { readonly kind: 'failure'; readonly code: string; readonly perPath: readonly NormalizedPath[] }
  | { readonly kind: 'contested'; readonly perPath: readonly NormalizedPath[] }
  | { readonly kind: 'mechanism'; readonly message: string };

export interface OracleInput {
  readonly graph: LineageGraph;
  readonly binding: ConditionalVersionBinding;
  readonly candidate: IdentityVersionID;
  readonly assessments: readonly ContinuityAssessment[];
  readonly policy: Policy;
  readonly ctx: TemporalContext;
}

export type OracleResult = { readonly ok: true; readonly result: NormalizedResult } | { readonly ok: false; readonly error: string };

interface SimpleEdge {
  readonly child: IdentityVersionID;
  readonly parent: IdentityVersionID;
  readonly relation: Relation;
}

interface EdgeAssessment {
  readonly status: 'SATISFIED' | 'NO_APPLICABLE' | 'UNSATISFIED' | 'CONTESTED';
  readonly missing?: readonly string[];
  readonly disallowed?: readonly string[];
  readonly contestedClaims?: readonly string[];
}

type EdgeEvaluation = { readonly ok: true; readonly value: EdgeAssessment } | { readonly ok: false; readonly error: string };

function compareStrings(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function permitted(scope: LineageTraversalScope, relation: Relation): boolean {
  if (scope === 'CONTINUATION_ONLY') {
    return relation === 'CONTINUATION';
  }
  if (scope === 'CONTINUATION_AND_FORK') {
    return relation === 'CONTINUATION' || relation === 'FORKED_FROM';
  }
  return true;
}

function triple(edge: SimpleEdge): EdgeTriple {
  return [String(edge.child), String(edge.parent), edge.relation];
}

function edgeKey(edge: SimpleEdge): string {
  return triple(edge).join('\u0000');
}

export function pathKey(scope: string, edges: readonly EdgeTriple[]): string {
  return JSON.stringify({ scope, edges });
}

function sortedEdges(edges: readonly SimpleEdge[]): SimpleEdge[] {
  return [...edges].sort(
    (left, right) =>
      compareStrings(String(left.child), String(right.child)) ||
      compareStrings(String(left.parent), String(right.parent)) ||
      compareStrings(left.relation, right.relation),
  );
}

/** Exhaustive DFS over scope-permitted simple paths from candidate to origin. */
function enumeratePaths(
  graph: LineageGraph,
  scope: LineageTraversalScope,
  candidate: IdentityVersionID,
  origin: IdentityVersionID,
): SimpleEdge[][] {
  const outbound = new Map<string, SimpleEdge[]>();
  for (const edge of graph.edges) {
    if (!permitted(scope, edge.relation)) {
      continue;
    }
    const key = String(edge.child);
    const list = outbound.get(key) ?? [];
    list.push({ child: edge.child, parent: edge.parent, relation: edge.relation });
    outbound.set(key, list);
  }
  for (const list of outbound.values()) {
    list.sort(
      (left, right) =>
        compareStrings(String(left.parent), String(right.parent)) ||
        compareStrings(left.relation, right.relation),
    );
  }

  if (candidate === origin) {
    return [];
  }

  const paths: SimpleEdge[][] = [];
  const visited = new Set<string>([String(candidate)]);
  const stack: SimpleEdge[] = [];

  const walk = (node: IdentityVersionID): void => {
    if (node === origin) {
      paths.push([...stack]);
      return;
    }
    for (const edge of outbound.get(String(node)) ?? []) {
      const parentKey = String(edge.parent);
      if (visited.has(parentKey)) {
        continue;
      }
      visited.add(parentKey);
      stack.push(edge);
      walk(edge.parent);
      stack.pop();
      visited.delete(parentKey);
    }
  };

  walk(candidate);
  return paths.sort((left, right) => compareStrings(pathKey(scope, left.map(triple)), pathKey(scope, right.map(triple))));
}

function evaluateEdge(
  edge: SimpleEdge,
  assessments: readonly ContinuityAssessment[],
  requirement: ContinuityAssuranceRequirement,
  policy: Policy,
  ctx: TemporalContext,
): EdgeEvaluation {
  const reference: EdgeRef = edge;
  const applicable = assessEdge(reference, assessments, policy, ctx);
  if (!applicable.ok) {
    return { ok: false, error: applicable.error.message };
  }
  if (applicable.value.unresolved) {
    return {
      ok: true,
      value: {
        status: 'NO_APPLICABLE',
        missing: [...requirement.required_claims].sort(compareStrings),
        disallowed: [],
      },
    };
  }

  const assurance = evaluateAssurance(applicable.value, requirement, policy, ctx);
  if ('kind' in assurance) {
    return { ok: false, error: assurance.message };
  }
  if (assurance.status === 'SATISFIED') {
    return { ok: true, value: { status: 'SATISFIED' } };
  }
  if (assurance.status === 'UNSATISFIED') {
    return {
      ok: true,
      value: { status: 'UNSATISFIED', missing: assurance.missing, disallowed: assurance.disallowed },
    };
  }
  return { ok: true, value: { status: 'CONTESTED', contestedClaims: assurance.contestedClaims } };
}

function directParents(graph: LineageGraph, child: IdentityVersionID): SimpleEdge[] {
  const seen = new Set<string>();
  const parents: SimpleEdge[] = [];
  for (const edge of graph.edges) {
    if (edge.child !== child) {
      continue;
    }
    const key = edgeKey(edge);
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    parents.push({ child: edge.child, parent: edge.parent, relation: edge.relation });
  }
  return sortedEdges(parents);
}

function validateOnePath(
  path: readonly SimpleEdge[],
  graph: LineageGraph,
  requirement: ContinuityAssuranceRequirement,
  assessments: readonly ContinuityAssessment[],
  policy: Policy,
  ctx: TemporalContext,
): { readonly ok: true; readonly outcome: NormalizedPath['outcome']; readonly closure?: NormalizedPath['closure'] } | { readonly ok: false; readonly error: string } {
  for (const edge of path) {
    const evaluation = evaluateEdge(edge, assessments, requirement, policy, ctx);
    if (!evaluation.ok) {
      return evaluation;
    }
    if (evaluation.value.status === 'SATISFIED') {
      continue;
    }
    if (evaluation.value.status === 'NO_APPLICABLE') {
      return {
        ok: true,
        outcome: {
          status: 'INVALID',
          code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
          missing: evaluation.value.missing,
          disallowed: evaluation.value.disallowed,
        },
      };
    }
    if (evaluation.value.status === 'UNSATISFIED') {
      return {
        ok: true,
        outcome: {
          status: 'INVALID',
          code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
          missing: evaluation.value.missing,
          disallowed: evaluation.value.disallowed,
        },
      };
    }
    return {
      ok: true,
      outcome: { status: 'CONTESTED', contestedClaims: evaluation.value.contestedClaims },
    };
  }

  const closure = immediateClosure(path, graph, requirement, assessments, policy, ctx);
  if (!closure.ok) {
    return closure;
  }
  return { ok: true, outcome: { status: 'VALID' }, closure: closure.closure };
}

/**
 * Immediate closure: for every path edge whose child is a merge node, check all
 * direct parent edges except the exact path edge. No recursion.
 */
function immediateClosure(
  path: readonly SimpleEdge[],
  graph: LineageGraph,
  requirement: ContinuityAssuranceRequirement,
  assessments: readonly ContinuityAssessment[],
  policy: Policy,
  ctx: TemporalContext,
): { readonly ok: true; readonly closure: NormalizedPath['closure'] } | { readonly ok: false; readonly error: string } {
  const failures = new Map<string, NormalizedFailure>();

  for (const edge of path) {
    const parents = directParents(graph, edge.child);
    if (!parents.some((parent) => parent.relation === 'MERGED_FROM')) {
      continue;
    }
    for (const branch of parents) {
      if (branch.parent === edge.parent && branch.relation === edge.relation) {
        continue;
      }
      const key = edgeKey(branch);
      if (failures.has(key)) {
        continue;
      }
      const evaluation = evaluateEdge(branch, assessments, requirement, policy, ctx);
      if (!evaluation.ok) {
        return evaluation;
      }
      if (evaluation.value.status === 'SATISFIED') {
        continue;
      }
      if (evaluation.value.status === 'NO_APPLICABLE') {
        failures.set(key, { branch: triple(branch), reason: 'NO_APPLICABLE_ASSESSMENT' });
      } else if (evaluation.value.status === 'UNSATISFIED') {
        failures.set(key, {
          branch: triple(branch),
          reason: 'ASSURANCE_UNSATISFIED',
          missing: evaluation.value.missing,
          disallowed: evaluation.value.disallowed,
        });
      } else {
        failures.set(key, {
          branch: triple(branch),
          reason: 'CONTESTED',
          contestedClaims: evaluation.value.contestedClaims,
        });
      }
    }
  }

  const ordered = [...failures.values()].sort(
    (left, right) =>
      compareStrings(left.branch[0], right.branch[0]) ||
      compareStrings(left.branch[1], right.branch[1]) ||
      compareStrings(left.branch[2], right.branch[2]),
  );
  return ordered.length === 0
    ? { ok: true, closure: { status: 'SATISFIED' } }
    : {
        ok: true,
        closure: { status: 'UNSATISFIED', code: 'ERR_MERGE_BRANCH_UNSATISFIED', failures: ordered },
      };
}

/**
 * Brute-force immediate-closure reference.
 *
 * Aggregation mirrors the current implementation: fully accepted path wins;
 * then closure failure, cycle, contested, assurance. This is implementation
 * behavior used to detect regressions; A-8 remains OPEN.
 */
export function runOracle(input: OracleInput): OracleResult {
  const { graph, binding, candidate, assessments, policy, ctx } = input;

  if (graph.cycles.length > 0) {
    return { ok: false, error: 'oracle is DAG-only; cyclic graph passed to the immediate-closure oracle' };
  }

  const paths = enumeratePaths(graph, binding.traversal_scope, candidate, binding.origin_version_id);
  const perPath: NormalizedPath[] = [];
  for (const path of paths) {
    const evaluated = validateOnePath(path, graph, binding.assurance_requirement, assessments, policy, ctx);
    if (!evaluated.ok) {
      return evaluated;
    }
    const edges = path.map(triple);
    perPath.push({
      key: pathKey(binding.traversal_scope, edges),
      scope: binding.traversal_scope,
      edges,
      outcome: evaluated.outcome,
      ...(evaluated.closure === undefined ? {} : { closure: evaluated.closure }),
    });
  }

  const accepted = perPath
    .filter((item) => item.outcome.status === 'VALID' && item.closure?.status === 'SATISFIED')
    .map((item) => item.key)
    .sort(compareStrings);
  if (accepted.length > 0) {
    return { ok: true, result: { kind: 'eligible', accepted, perPath } };
  }
  if (paths.length === 0) {
    return { ok: true, result: { kind: 'no-path' } };
  }
  if (perPath.some((item) => item.closure?.status === 'UNSATISFIED')) {
    return { ok: true, result: { kind: 'failure', code: 'ERR_MERGE_BRANCH_UNSATISFIED', perPath } };
  }
  if (perPath.some((item) => item.outcome.status === 'CONTESTED')) {
    return { ok: true, result: { kind: 'contested', perPath } };
  }
  return {
    ok: true,
    result: { kind: 'failure', code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED', perPath },
  };
}

/**
 * Comparison-only normalizer for production `BindingResult` values.
 * The oracle builds the same shape independently; this module is never
 * imported by the oracle.
 */
import type { MergeClosureResult, Path, PathOutcome, PathValidation, BindingResult } from '../../../src/core/traversal.js';
import type { EdgeTriple, NormalizedFailure, NormalizedPath, NormalizedResult } from './merge-oracle.js';
import { pathKey } from './merge-oracle.js';

function compareStrings(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function edgesOf(path: Path): readonly EdgeTriple[] {
  return path.edges.map((edge) => [String(edge.child), String(edge.parent), edge.relation] as const);
}

function normalizeFailure(failure: MergeClosureResult extends infer _ ? never : never): never {
  throw new Error('unreachable');
}

function normalizeClosureFailure(failure: Extract<MergeClosureResult, { status: 'UNSATISFIED' }>['failures'][number]): NormalizedFailure {
  const branch: EdgeTriple = [String(failure.branch.child), String(failure.branch.parent), failure.branch.relation];
  if (failure.reason === 'NO_APPLICABLE_ASSESSMENT') {
    return { branch, reason: failure.reason };
  }
  if (failure.reason === 'ASSURANCE_UNSATISFIED') {
    return { branch, reason: failure.reason, missing: failure.missing, disallowed: failure.disallowed };
  }
  return { branch, reason: failure.reason, contestedClaims: failure.contestedClaims };
}

function normalizeClosure(closure: MergeClosureResult): NonNullable<NormalizedPath['closure']> {
  if (closure.status === 'SATISFIED') {
    return { status: 'SATISFIED' };
  }
  return {
    status: 'UNSATISFIED',
    code: closure.code,
    failures: closure.failures.map(normalizeClosureFailure),
  };
}

function normalizeOutcome(outcome: PathValidation): NormalizedPath['outcome'] {
  if (outcome.status === 'VALID') {
    return { status: 'VALID' };
  }
  if (outcome.status === 'INVALID') {
    return {
      status: 'INVALID',
      code: outcome.code,
      missing: outcome.missing,
      disallowed: outcome.disallowed,
    };
  }
  if (outcome.status === 'CONTESTED') {
    return { status: 'CONTESTED', contestedClaims: outcome.contestedClaims };
  }
  return { status: 'CYCLE_DETECTED', code: outcome.code };
}

export function normalizePathOutcome(item: PathOutcome): NormalizedPath {
  const edges = edgesOf(item.path);
  return {
    key: pathKey(item.path.scope, edges),
    scope: item.path.scope,
    edges,
    outcome: normalizeOutcome(item.outcome),
    ...(item.closure === undefined ? {} : { closure: normalizeClosure(item.closure) }),
  };
}

export function normalizeProduction(result: BindingResult): NormalizedResult {
  if (result.eligible) {
    const perPath = result.details.perPath.map(normalizePathOutcome).sort((left, right) => compareStrings(left.key, right.key));
    return {
      kind: 'eligible',
      accepted: result.acceptedPaths.map((path) => pathKey(path.scope, edgesOf(path))).sort(compareStrings),
      perPath,
    };
  }
  if ('kind' in result) {
    if (result.kind === 'MECHANISM') {
      return { kind: 'mechanism', message: result.error.message };
    }
    return {
      kind: 'contested',
      perPath: result.details.perPath.map(normalizePathOutcome).sort((left, right) => compareStrings(left.key, right.key)),
    };
  }
  if (result.code === 'ERR_NO_TRAVERSAL_PATH') {
    return { kind: 'no-path' };
  }
  return {
    kind: 'failure',
    code: result.code,
    perPath: (result.details.perPath ?? [])
      .map(normalizePathOutcome)
      .sort((left, right) => compareStrings(left.key, right.key)),
  };
}

/** Canonical failure order: child, parent, relation. */
export function canonicalFailureKeys(closure: Extract<MergeClosureResult, { status: 'UNSATISFIED' }>): string[] {
  return closure.failures
    .map((failure) => `${String(failure.branch.child)}|${String(failure.branch.parent)}|${failure.branch.relation}`)
    .sort(compareStrings);
}

