    );

    expectNotEligible(result);
    if (result.eligible || !('code' in result)) return;
    expect(result.code).toBe('ERR_ASSURANCE_PREDICATE_UNSATISFIED');
    expect(result.details.perPath?.[0]?.outcome.status).toBe('INVALID');
  });

